old_string:
SegmentedButton<String>(
  segments: const [
    ButtonSegment(
      value: AppConstants.BLOCKLinkWifi,
      label: Text('Wi‑Fi'),
      icon: Icon(Icons.wifi),
    ),
    ButtonSegment(
      value: AppConstants.BLOCKLinkGsm,
      label: Text('GSM (SIM)'),
      icon: Icon(Icons.cell_tower),
    ),
  ],
  selected: {_linkMode},
  onSelectionChanged: (s) {
    if (s.isEmpty) return;
    setState(() => _linkMode = s.first);
  },
),
const SizedBox(height: 8),
Text(
  _linkMode == AppConstants.BLOCKLinkWifi
      ? 'Блок в зоне Wi‑Fi объекта.'
      : 'Блок без Wi‑Fi — SIM900A + SIM.',
  style: theme.textTheme.bodySmall?.copyWith(
    color: theme.colorScheme.onSurfaceVariant,
  ),
),

new_string:
SegmentedButton<String>(
  segments: const [
    ButtonSegment(
      value: AppConstants.BLOCKLinkWifi,
      label: Text('Wi‑Fi'),
      icon: Icon(Icons.wifi),
    ),
    ButtonSegment(
      value: AppConstants.BLOCKLinkAuto,
      label: Text('Auto'),
      icon: Icon(Icons.swap_horiz),
    ),
    ButtonSegment(
      value: AppConstants.BLOCKLinkGsm,
      label: Text('GSM'),
      icon: Icon(Icons.cell_tower),
    ),
  ],
  selected: {_linkMode},
  onSelectionChanged: (s) {
    if (s.isEmpty) return;
    setState(() => _linkMode = s.first);
  },
),
const SizedBox(height: 8),
Text(
  _linkMode == AppConstants.BLOCKLinkAuto
      ? 'Нет Wi‑Fi → GSM; нет GSM → Wi‑Fi. Нужны и SSID, и APN.'
      : _linkMode == AppConstants.BLOCKLinkWifi
          ? 'Только Wi‑Fi объекта.'
          : 'Только SIM900A + SIM.',
